  "Instagram:": "Instagram：",
  "Eine unmittelbare Kontaktaufnahme ist telefonisch und per E-Mail möglich. Das Kontaktformular dieser Website übermittelt eingegebene Daten über den Formular-Dienst FormSubmit an dominik@campdoerfl.de.": "您可以通过电话或电子邮件直接联系。本网站的联系表单通过表单服务 FormSubmit 将填写的内容发送至 dominik@campdoerfl.de。",
  "Rechtliche Schnellnavigation": "法律页面快速导航",
  "Cookies & lokale Speicherungen": "Cookie 与本地存储",
  "Verantwortlich für den Inhalt nach § 18 Abs. 2 MStV": "依据德国《媒体州际协定》第 18 条第 2 款的内容负责人",
  "Verbraucherstreitbeilegung": "消费者争议解决",
  "Ich bin nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.": "本人无意也无义务参加消费者仲裁机构的争议解决程序。",
  "Hinweis: Die frühere EU-Online-Streitbeilegungsplattform wurde zum 20. Juli 2025 eingestellt.": "提示：原欧盟在线争议解决平台已于 2025年7月20日 停止运行。",
  "Hinweis zu Werbung, Partnerlinks und Kooperationen": "关于广告、合作链接与合作关系的说明",
  "Auf dieser Website können Inhalte mit Markenbezug, Partnernennungen, Rabattcodes oder direkten Partnerlinks erscheinen. Hinweise zur Kennzeichnung und Transparenz finden Sie auf der Seite": "本网站可能出现与品牌相关的内容、合作方名称、优惠码或直接的合作链接。有关标注与透明度的说明见",
  "Urheberrecht": "著作权",
  "Die auf dieser Website veröffentlichten Texte, Bilder, Grafiken und sonstigen Inhalte unterliegen dem Urheberrecht, soweit nicht anders gekennzeichnet. Eine Nutzung außerhalb der gesetzlichen Grenzen bedarf der vorherigen Zustimmung.": "除另有标注外，本网站发布的文字、图片、图形及其他内容均受著作权保护。超出法律允许范围的使用须事先取得同意。",
  "Geltungsbereich des Impressums": "本声明的适用范围",
  "Dieses Impressum gilt für die Website von Camp Dörfl unter campdoerfl.de und für die dort dargestellten Angebote rund um Premium Personal Training, Firmenfitness, Events, Kooperationen und die Camp Dörfl App.": "本法律声明适用于 campdoerfl.de 上的 Camp Dörfl 网站，以及其中介绍的高端私教、企业健身、活动、合作与 Camp Dörfl 应用等服务。",
  "Zusätzliche Profile auf externen Plattformen können eigene Anbieterinformationen, Nutzungsbedingungen und Datenschutzangaben enthalten.": "外部平台上的其他账号可能有各自的经营者信息、使用条款与隐私说明。",
  "Kommunikation und Anfragen": "沟通与咨询",
  "Für Fragen zu Inhalten, Kooperationen, rechtlichen Hinweisen oder einer Zusammenarbeit in Nürnberg ist die im Impressum genannte E-Mail-Adresse der direkte Kontaktweg.": "关于内容、合作、法律提示或在纽伦堡开展合作的问题，本声明中列出的邮箱是最直接的联系方式。",
  "Bei geschäftlichen Anfragen bitte den betroffenen Bereich nennen, damit Premium Personal Training, Firmenfitness, Events oder App-Themen schnell richtig zugeordnet werden können.": "商务咨询请注明所涉领域，以便高端私教、企业健身、活动或应用相关事项能被迅速正确分流。",
  "Redaktionelle Verantwortung": "内容责任",
  "Die Inhalte der Website werden mit dem Anspruch gepflegt, Leistungen, Kontaktwege und rechtliche Hinweise verständlich und aktuell darzustellen. Änderungen an Angeboten, Partnern oder technischen Diensten können eine Anpassung einzelner Informationsseiten erforderlich machen.": "网站内容以清晰、及时地呈现服务、联系方式与法律提示为标准进行维护。服务、合作方或技术供应商发生变动时，个别信息页面可能需要相应调整。",
  "Falls Ihnen eine unklare Angabe, ein fehlerhafter Link oder ein missverständlicher Hinweis auffällt, können Sie sich direkt über die genannte Kontaktadresse melden.": "如果您发现表述不清、链接失效或容易引起误解的说明，可直接通过上述联系方式告知。",

