  "Partnerlinks & Werbung | Camp Dörfl": "合作链接与广告 | Camp Dörfl",
  "Transparenz bei Camp Dörfl: Hinweise zu Partnerlinks, Rabattcodes, Kooperationen, Werbung, Markenempfehlungen und kommerziellen Inhalten.": "Camp Dörfl 的透明度说明：合作链接、优惠码、合作关系、广告、品牌推荐与商业内容。",
  "Diese Seite erläutert, wie Camp Dörfl mit Werbung, Kooperationen, Markenhinweisen und direkten Partnerlinks umgeht. Stand: 17. Juni 2026.": "本页说明 Camp Dörfl 如何处理广告、合作、品牌提及与直接合作链接。更新于 2026年6月17日。",
  "Kurz zusammengefasst": "简要说明",
  "Auf dieser Website können Marken, Produkte, Logos, Kooperationen, Rabattcodes und Partnerlinks genannt oder verlinkt werden.": "本网站可能提及或链接品牌、产品、标识、合作关系、优惠码与合作链接。",
  "Solche Inhalte werden auf den jeweiligen Seiten kenntlich gemacht oder sind aus dem Kontext als Kooperation, Werbung oder Partnerhinweis erkennbar.": "此类内容会在相应页面上标注，或可从上下文看出属于合作、广告或合作方提示。",
  "Einzelne Links können direkte Partnerlinks oder Referral-Links sein und damit wirtschaftlich relevant für Camp Dörfl sein.": "个别链接可能是直接的合作链接或推荐链接，因而对 Camp Dörfl 具有经济意义。",
  "Fragen zur Kennzeichnung oder zu einer konkreten Kooperation können jederzeit per E-Mail gestellt werden.": "关于标注方式或某项具体合作的问题，随时可以通过电子邮件提出。",
  "Aktueller Stand auf dieser Website": "本网站的当前情况",
  "Auf der Partner-Seite werden aktuell unter anderem XXL Nutrition und AEKE vorgestellt.": "合作伙伴页面目前介绍了 XXL Nutrition 和 AEKE 等品牌。",
  "Bei AEKE wird derzeit ein direkter Partnerlink mit Referral-Parameter genutzt.": "对 AEKE 目前使用带推荐参数的直接合作链接。",
  "Bei XXL Nutrition wird derzeit unter anderem der Code": "对 XXL Nutrition 目前使用的优惠码是",
  "Dominik": "Dominik",
  "genannt.": "。",
  "Die Partner-Seite und dazugehörige Buttons werden technisch mit": "合作伙伴页面及相关按钮在技术上标注为",
  "rel=\"sponsored\"": "rel=\"sponsored\"",
  "gekennzeichnet.": "。",
  "1. Kennzeichnung von Werbung und Kooperationen": "1. 广告与合作的标注",
  "Wenn Camp Dörfl Marken, Produkte oder Unternehmen im Rahmen einer Kooperation vorstellt, geschieht dies als kommerzielle Kommunikation im Sinne der geltenden Informationspflichten. Solche Inhalte werden auf der jeweiligen Seite sprachlich, gestalterisch oder über den Kontext als Partnerinhalt erkennbar gemacht.": "当 Camp Dörfl 在合作框架下介绍品牌、产品或企业时，这属于相关信息义务意义上的商业传播。此类内容会通过措辞、版式或上下文，在相应页面上被识别为合作内容。",
  "2. Partnerlinks und Referral-Links": "2. 合作链接与推荐链接",
  "Einzelne externe Links können direkt zu Partner-Angeboten führen und technisch Parameter enthalten, die eine Zuordnung der Empfehlung ermöglichen, beispielsweise Referral- oder Tracking-Parameter wie": "个别外部链接可能直接指向合作方的产品，并在技术上带有可用于归因推荐的参数，例如推荐或跟踪参数",
  "sca_ref": "sca_ref",
  "Wenn Sie einem solchen Link folgen oder einen genannten Code verwenden, kann Camp Dörfl hierdurch wirtschaftlich begünstigt werden.": "如果您点击此类链接或使用文中提到的优惠码，Camp Dörfl 可能因此获得经济收益。",
  "3. Rabattcodes und Vorteile": "3. 优惠码与优惠",
  "Genannte Rabattcodes, Hinweise auf Aktionen oder Produktvorteile dienen der transparenten Kommunikation mit Interessierten. Ob und in welcher Höhe ein Vorteil für Sie entsteht, richtet sich ausschließlich nach dem aktuellen Angebot des jeweiligen Partners.": "文中提到的优惠码、活动提示或产品优惠，是为了与感兴趣的读者保持透明沟通。您能否获得优惠、优惠幅度多大，完全取决于合作方当时的活动条件。",
  "4. Einordnung und Verantwortung": "4. 判断与责任",
  "Kooperationen werden nur dann eingebunden, wenn sie aus Sicht von Camp Dörfl fachlich, inhaltlich und markenseitig zum eigenen Performance-System passen. Die Erwähnung einer Marke ersetzt jedoch keine eigene Prüfung durch Nutzerinnen und Nutzer.": "只有在 Camp Dörfl 认为在专业、内容与品牌层面都契合自身体系时，才会引入合作。但提及某个品牌并不能替代用户自己的判断。",
  "Fragen zur Transparenz": "关于透明度的问题",
  "Wenn Sie wissen möchten, ob eine konkrete Erwähnung, Verlinkung oder Empfehlung auf dieser Website im Rahmen einer Kooperation erfolgt, schreiben Sie bitte an": "如果您想了解本网站上的某处提及、链接或推荐是否属于合作内容，请写信至",
  "Diese Hinweise gelten für den aktuellen Stand der Website und müssen aktualisiert werden, wenn weitere Partner, Affiliate-Modelle oder Werbeformate hinzukommen.": "本说明反映网站的当前状况。若增加新的合作方、联盟模式或广告形式，须相应更新。",
  "Expertenwissen: Training & Bodybuilding | Dominik Dörfl": "专业知识：训练与健美 | Dominik Dörfl",
  "Fundierte Leitfäden von Dominik Dörfl zu Personal Training, Bodybuilding-Wettkampfvorbereitung, BIA, InBody und Körperanalyse.": "Dominik Dörfl 撰写的扎实指南，涵盖私人教练课程、健美备赛、BIA、InBody 与体成分分析。",
