  "Fachwissen zu Personal Training, Bodybuilding, Körperanalyse und Performance – mit direkter Antwort, nachvollziehbarer Einordnung und belastbaren Originalquellen.": "关于私人教练课程、健美、体成分分析与运动表现的专业知识：先给答案，再讲清依据，并附上可核查的原始来源。",
