  "Contest Prep": "备赛",
  "Wie lange dauert eine Wettkampfvorbereitung?": "备赛需要多长时间？",
  "Warum Ausgangslage und nachhaltige Abnahmerate wichtiger sind als ein fixes Datum.": "为什么起点和可持续的减重速度比一个固定日期更重要。",
  "Körperanalyse": "体成分分析",
  "BIA, InBody oder 2D-Analyse?": "BIA、InBody 还是 2D 分析？",
  "Was die Verfahren zeigen, wo ihre Grenzen liegen und wie Verlaufsdaten sinnvoll werden.": "各种方法能说明什么、局限在哪里，以及如何让连续数据真正有用。",
  "Transparenz": "透明",
  "So entstehen die Inhalte.": "这些内容是怎么写成的。",
  "Eigene Coaching-Erfahrung wird als Erfahrung gekennzeichnet. Wissenschaftliche Aussagen verlinken auf Primärliteratur, Fachgesellschaften oder offizielle Ergebnisquellen.": "自身的指导经验会被明确标注为经验。科学论断则链接到原始文献、专业学会或官方成绩来源。",
  "Direkte Antwort zuerst": "先给答案",
  "Die Kernaussage steht am Anfang und bleibt auch ohne Fachsprache verständlich.": "核心结论放在开头，不用专业术语也能看懂。",
  "Belege am Anspruch": "论据要配得上论断",
  "Je größer oder sensibler eine Aussage, desto stärker muss ihre Quelle sein.": "论断越重大或越敏感，其来源就必须越有力。",
  "Aktualisierung sichtbar": "更新公开可见",
  "Veröffentlichungs- und Prüfdatum werden auf jeder Fachseite genannt.": "每个专业页面都标明发布日期与审阅日期。",
  "Vollständige redaktionelle Richtlinien ansehen →": "查看完整编辑准则 →",
  "Persönliche Einordnung": "一对一解读",
  "Du brauchst keine allgemeine Antwort, sondern eine für deinen Ausgangspunkt?": "需要的不是通用答案，而是针对你自身情况的答案？",
  "Dann klären wir Ziel, Alltag und sinnvolle nächsten Schritte persönlich.": "那我们就当面理清目标、日常安排与合适的下一步。",
  "Cookies & lokale Speicherungen | Camp Dörfl": "Cookie 与本地存储 | Camp Dörfl",
  "Cookie-Hinweise von Camp Dörfl: lokale Speicherungen, Consent-Einstellungen, externe Medien und Widerruf auf campdoerfl.de.": "Camp Dörfl 的 Cookie 说明：campdoerfl.de 上的本地存储、同意设置、外部媒体与撤回方式。",
  "Diese Seite beschreibt, welche Cookies, lokalen Speicherungen und externen Medien auf dieser Website aktuell eingesetzt werden. Stand: 17. Juni 2026.": "本页说明本网站目前使用哪些 Cookie、本地存储与外部媒体。更新于 2026年6月17日。",
  "Es werden aktuell keine Analyse-, Marketing- oder Remarketing-Cookies automatisch gesetzt.": "目前不会自动设置任何分析、营销或再营销类 Cookie。",
  "Für das Einwilligungs-Management nutzt die Website derzeit vor allem eine lokale Speicherung im Browser statt klassischer Tracking-Cookies.": "在同意管理方面，本网站目前主要使用浏览器中的本地存储，而不是传统的跟踪 Cookie。",
  "YouTube-Videos werden erst nach Ihrer Freigabe für externe Medien geladen und können danach im sichtbaren Bereich automatisch stumm starten.": "YouTube 视频只有在您同意加载外部媒体后才会加载，之后可能在进入可见区域时自动静音播放。",
  "Die Einstellungen können jederzeit erneut geöffnet, geändert oder widerrufen werden.": "相关设置随时可以重新打开、修改或撤回。",
  "Einwilligung verwalten": "管理同意设置",
  "Sie können Ihre Auswahl jederzeit erneut aufrufen, ändern oder widerrufen.": "您可以随时重新查看、修改或撤回自己的选择。",
  "Cookie-Einstellungen öffnen": "打开 Cookie 设置",
  "Rechtsgrundlagen: § 25 TDDDG sowie, soweit personenbezogene Daten verarbeitet werden, Art. 6 DSGVO.": "法律依据：德国《电信数字服务数据保护法》第 25 条；在涉及个人数据处理时，还包括《通用数据保护条例》第 6 条。",
  "1. Einwilligungs-Speicherung im Browser": "1. 在浏览器中保存同意选择",
  "Diese Website speichert Ihre Einwilligungsentscheidung lokal in Ihrem Browser, damit die getroffene Auswahl bei weiteren Seitenaufrufen beachtet werden kann.": "本网站会把您的同意选择保存在浏览器本地，以便在后续访问中沿用该设置。",
  "Technischer Name:": "技术名称：",
  "campdoerfl-consent": "campdoerfl-consent",
  "Inhalt:": "内容：",
  "Auswahl zu externen Medien, Versionsstand und Zeitstempel der Speicherung": "对外部媒体的选择、版本号以及保存时间",
  "Zweck:": "用途：",
  "Speicherung Ihrer Auswahl zu erforderlichen Funktionen und externen Medien": "保存您对必要功能与外部媒体的选择",
  "Speicherdauer:": "保存期限：",
  "bis zur manuellen Löschung im Browser oder bis eine neue Consent-Version erforderlich wird": "直到您在浏览器中手动删除，或直到需要新的同意版本为止",
  "Rechtsgrundlage:": "法律依据：",
  "§ 25 Abs. 2 Nr. 2 TDDDG sowie Art. 6 Abs. 1 lit. f DSGVO.": "德国《电信数字服务数据保护法》第 25 条第 2 款第 2 项，以及《通用数据保护条例》第 6 条第 1 款 f 项。",
  "2. Externe Medien": "2. 外部媒体",
  "Auf mehreren Seiten dieser Website sind YouTube-Videos im erweiterten Datenschutzmodus eingebunden. Diese Inhalte werden erst nach Ihrer Freigabe für externe Medien geladen.": "本网站的多个页面以增强隐私模式嵌入了 YouTube 视频。这些内容只有在您同意加载外部媒体后才会载入。",
  "Nach der Freigabe kann beim Erreichen des sichtbaren Bereichs automatisch eine Verbindung zu YouTube beziehungsweise Google hergestellt werden. Die Videos starten dabei stumm; den Ton können Sie bei Bedarf direkt im Player aktivieren.": "同意之后，当视频进入可见区域时，可能会自动与 YouTube 或 Google 建立连接。视频会静音开始播放，您可以在播放器中自行打开声音。",
  "§ 25 Abs. 1 TDDDG sowie Art. 6 Abs. 1 lit. a DSGVO.": "德国《电信数字服务数据保护法》第 25 条第 1 款，以及《通用数据保护条例》第 6 条第 1 款 a 项。",
  "3. Aktuell nicht im Einsatz": "3. 目前未使用的技术",
  "Zum Stand vom 17. Juni 2026 werden auf dieser Website aktuell keine einwilligungspflichtigen Analyse- oder Marketing-Tools wie Tracking-Pixel, Werbe-Cookies, Remarketing-Dienste oder Social-Media-Embeds automatisch aktiviert.": "截至 2026年6月17日，本网站不会自动启用任何需要同意的分析或营销工具，例如跟踪像素、广告 Cookie、再营销服务或社交媒体嵌入。",
  "4. Browser-Einstellungen und Widerruf": "4. 浏览器设置与撤回",
  "Sie können lokale Speicherungen jederzeit über Ihre Browser-Einstellungen löschen. Zusätzlich können Sie Ihre Auswahl direkt über den Link „Cookie-Einstellungen“ im Footer neu setzen.": "您可以随时在浏览器设置中删除本地存储，也可以直接通过页脚的“Cookie 设置”链接重新做出选择。",
  "Wenn künftig weitere Dienste eingebunden werden, insbesondere Analyse-, Werbe- oder Social-Media-Plugins, müssen diese Seite, die Datenschutzerklärung und die Consent-Logik vor der Aktivierung entsprechend erweitert werden.": "今后若接入更多服务，尤其是分析、广告或社交媒体插件，本页面、隐私政策与同意逻辑必须在启用前相应扩充。",

