  "Ob Premium Personal Training, Firmenfitness, Events, App oder Kooperation: hier startet der direkte Kontakt für alle Anfragearten auf der Seite.": "无论是高端私教、企业健身、活动、应用还是合作，本页面上所有类型的咨询都从这里开始。",
  "Trag einfach deine Kontaktdaten und dein Anliegen ein. Die Nachricht wird direkt an dominik@campdoerfl.de gesendet.": "填写您的联系方式和需求即可。消息将直接发送至 dominik@campdoerfl.de。",
