  "Klar, persönlich und direkt zur richtigen Anfrage.": "清楚、亲自、直达合适的咨询入口。",
  "Der Kontakt soll ohne Umwege funktionieren: kurz beschreiben, worum es geht, Bereich auswählen und absenden.": "联系不该绕弯路：简单描述需求，选择相应领域，然后发送。",
