  "Wenn es um Premium Personal Training, Training ohne Bindung, Ernährung oder App-Zugang geht, hilft eine kurze Beschreibung von Ziel, Ausgangslage und gewünschter Begleitung.": "如果涉及高端私教、无约束训练、营养或应用权限，简单说明目标、当前状况和希望获得的陪伴方式会很有帮助。",
  "Personal Trainer Nürnberg: Leistungen und Erfolge ansehen": "纽伦堡私人教练：查看服务与成绩",
  "Bei Firmenfitness, Gesundheitstagen oder Performance Checks sind Unternehmensgröße, Standort, Zeitraum und gewünschtes Format die wichtigsten Eckdaten.": "对于企业健身、健康日或体能检测，最关键的信息是公司规模、地点、时间段与期望的形式。",
  "Für Events und Partner": "面向活动与合作方",
  "Für Moderation, Kooperationen oder Markenanfragen reicht zunächst ein Überblick über Anlass, Termin, Zielgruppe und gewünschte Rolle von Camp Dörfl.": "关于主持、合作或品牌咨询，先说明场合、日期、受众以及希望 Camp Dörfl 扮演的角色即可。",
  "Für schnelle Einordnung": "为了快速判断",
  "Je klarer die Anfrage formuliert ist, desto schneller lässt sich einschätzen, ob ein persönliches Gespräch, ein konkretes Angebot oder ein anderer nächster Schritt sinnvoll ist. So bleibt die Beratung direkt, persönlich und effizient.": "咨询写得越清楚，就越快能判断该安排一次面谈、给出具体方案，还是采取其他下一步。这样沟通才能保持直接、亲自而高效。",
  "Was danach passiert": "之后会发生什么",
  "Nach der Anfrage wird geprüft, welcher Bereich fachlich passt und welche Informationen noch fehlen. Danach folgt eine Rückmeldung mit einer klaren Empfehlung, ob ein Kennenlernen, ein Telefonat, ein Angebot oder eine kurze Rückfrage der beste nächste Schritt ist.": "收到咨询后，我们会先判断属于哪个领域、还缺哪些信息，然后给出明确建议：是先见一面、通个电话、直接出方案，还是再问一个问题。",
  "So bleibt der Austausch verbindlich, nachvollziehbar und passend zu deinem Anliegen, egal ob es um Training, Unternehmen, Bühne, App oder Kooperation geht.": "这样沟通才有分量、有条理，并且贴合您的需求，无论涉及训练、企业、舞台、应用还是合作。",
