  "Dominik Dörfl, Personal Trainer und Performance Coach in Nürnberg": "Dominik Dörfl，纽伦堡的私人教练与运动表现教练",
  "Autor &amp; Praxisexperte": "作者与实践专家",
  "Personal Trainer, Bodybuilding- und Performance-Coach in Nürnberg. Deutscher Meister im Bodybuilding und Powerlifting, IFBB Pro und Coach von Athletinnen und Athleten mit nationalen und internationalen Platzierungen.": "纽伦堡的私人教练、健美与运动表现教练。健美与力量举德国冠军，IFBB 职业选手，并指导过多位取得国内与国际名次的运动员。",
  "Fachlich geprüft und zuletzt aktualisiert: 11. August 2026": "专业审阅并最后更新：2026年8月11日",
