  "Partner & Kooperationen | Camp Dörfl": "合作伙伴与合作 | Camp Dörfl",
  "Partner und Kooperationen bei Camp Dörfl: glaubwürdige Markenpräsenz zwischen Performance, Events, Community, App und Unternehmen.": "Camp Dörfl 的合作伙伴与合作方式：在运动表现、活动、社群、应用与企业之间建立可信的品牌呈现。",
  "Partner und Marken von Camp Dörfl": "Camp Dörfl 的合作伙伴与品牌",
  "Partner & Kooperationen": "合作伙伴与合作",
  "Für welche Marken sind Partnerschaften mit Camp Dörfl interessant?": "哪些品牌适合与 Camp Dörfl 合作？",
  "Vor allem für Marken, Produkte und Orte, die zu Leistung, Gesundheit, Ernährung, Training, Präsenz oder Community passen und glaubwürdig im Alltag verankert werden sollen.": "主要是与运动表现、健康、营养、训练、舞台呈现或社群相契合的品牌、产品与场所，并且希望在日常生活中真实落地。",
  "Geht es nur um Social Media oder auch um reale Präsenz?": "只是社交媒体，还是也包括线下呈现？",
  "Beides ist möglich. Gerade die Verbindung aus Content, Event, Ort, Community und echter Anwendung macht Partnerschaften bei Camp Dörfl besonders wertvoll.": "两者都可以。正是内容、活动、场地、社群与真实使用的结合，让与 Camp Dörfl 的合作格外有价值。",
  "Sind auch regionale Kooperationen im Raum Nürnberg sinnvoll?": "在纽伦堡地区的本地合作有意义吗？",
  "Ja. Regionale Partnerschaften können besonders stark sein, wenn sie Training, Unternehmen, Events oder Community direkt vor Ort erlebbar machen.": "有。当本地合作能让训练、企业、活动或社群在当地被真实体验时，效果往往格外好。",
  "Wie startet eine Zusammenarbeit am besten?": "合作最好怎样开始？",
  "Mit einer kurzen Anfrage und einer ehrlichen Einordnung. Danach wird geprüft, ob Marke, Produkt, Zielgruppe und Format wirklich zusammenpassen.": "先发一封简短的咨询，得到一次坦诚的评估。之后再判断品牌、产品、目标人群与形式是否真的契合。",
  "Kooperation anfragen": "咨询合作",
  "Partner im Performance System": "运动表现体系中的合作伙伴",
  "Premium Partner im Camp": "Camp 的高级合作伙伴",
