  "Warum Partner": "为什么合作",
  "Wieso Camp Dörfl für Partnerschaften funktioniert.": "为什么与 Camp Dörfl 合作行得通。",
  "Kooperationen wirken hier nicht aufgesetzt, sondern eingebettet in Training, Bühne, Unternehmen und Alltag.": "这里的合作不显生硬，而是嵌入训练、舞台、企业与日常之中。",
  "Performance wird hier wirklich gelebt.": "运动表现在这里是真正被践行的。",
  "Camp Dörfl verbindet Athletik, Bühne, Training, Unternehmen und Community. Genau dadurch wirken Marken nicht aufgesetzt, sondern sauber eingebettet.": "Camp Dörfl 把竞技、舞台、训练、企业与社群连在一起。正因如此，品牌在这里显得自然，而不是硬贴上去的。",
  "Live, digital und im Alltag präsent.": "线下、线上与日常中同时在场。",
  "Kooperationen können über Events, Content, App-Umfeld, Community und direkte Produktnähe gleichzeitig sichtbar werden.": "合作可以同时通过活动、内容、应用环境、社群以及产品的真实使用被看见。",
  "Partnerschaften folgen Haltung statt Beliebigkeit.": "合作取决于立场，而不是随便谁都行。",
  "Nicht jede Marke passt. Entscheidend sind Qualität, Zielgruppenfit und eine Zusammenarbeit, die langfristig glaubwürdig bleibt.": "并非每个品牌都合适。关键是品质、受众契合度，以及一段长期看仍然可信的合作。",
  "Kooperationsfelder": "合作形式",
  "So kann Zusammen": "合作具体",
  "arbeit konkret aussehen.": "可以是什么样。",
  "Je nach Marke, Ziel und Format kann die Zusammenarbeit live, digital oder in einer Verbindung aus beidem aufgebaut werden.": "视品牌、目标与形式而定，合作可以在线下、线上，或两者结合的方式中展开。",
  "Live und Bühne": "线下与舞台",
  "Events, Moderation, Panels und Vor-Ort-Präsenz bringen Marken in einen professionellen und echten Rahmen.": "活动、主持、圆桌与现场呈现，把品牌放进一个专业而真实的场景。",
  "Content mit Alltagstiefe": "有生活厚度的内容",
  "Produkte und Partnerschaften können dort gezeigt werden, wo Training, Ernährung und Leistung wirklich stattfinden.": "产品与合作可以出现在训练、营养与运动表现真正发生的地方。",
  "App und digitales Umfeld": "应用与数字环境",
  "Digitale Berührungspunkte sorgen dafür, dass Kooperationen nicht nur kurz sichtbar, sondern wiederkehrend erlebbar werden.": "数字触点让合作不只是短暂露出，而是被反复体验到。",
  "Community und Orte": "社群与场地",
  "Mit Gym, Community, Unternehmen und Event-Formaten entstehen Berührungspunkte weit über klassische Werbung hinaus.": "健身房、社群、企业与活动形式共同创造出远超传统广告的接触点。",
