  "Executive Performance Coaching Nürnberg | Camp Dörfl": "纽伦堡高管体能指导 | Camp Dörfl",
  "Executive Performance von Camp Dörfl: 12-Wochen-Premium-Coaching in Nürnberg für Führungskräfte und Leistungsträger mit vollem Kalender – Analyse, Plan und App.": "Camp Dörfl 的高管体能计划：为日程繁忙的管理者与高绩效人士提供的纽伦堡 12 周高端指导，包含测评、计划与应用。",
  "Dominik Dörfl beim Krafttraining für Executive Performance Coaching": "Dominik Dörfl 在为高管体能指导进行力量训练",
  "Executive Performance Coaching Nürnberg": "纽伦堡高管体能指导",
  "12-Wochen-Premium-Coaching für Führungskräfte und Leistungsträger mit Analyse, Plan und App.": "面向管理者与高绩效人士的 12 周高端指导，包含测评、计划与应用。",
  "Wie viel Zeit kostet mich das Programm pro Woche?": "这个计划每周要占用我多少时间？",
  "Das Programm ist für volle Kalender gebaut. Training, Ernährung und Check-ins werden so geplant, dass sie sich in deinen Alltag einfügen, statt ihn zu sprengen.": "这个计划就是为繁忙日程设计的。训练、营养与阶段复查都会安排得嵌入你的日常，而不是把它撑破。",
  "Brauche ich Vorerfahrung im Training?": "我需要有训练基础吗？",
  "Nein. Wir starten mit einer ehrlichen Analyse deines Status und bauen den Plan exakt auf deine Ausgangslage, deine Ziele und deinen Beruf auf.": "不需要。我们先对你的现状做一次坦诚评估，再完全按你的起点、目标与职业来搭建计划。",
  "Warum nur wenige Plätze?": "为什么名额很少？",
  "Executive Performance ist persönlich geführt. Damit Qualität, Erreichbarkeit und Anpassung hoch bleiben, gibt es bewusst nur eine begrenzte Zahl an Plätzen.": "高管体能计划由本人亲自带。为了保证质量、随时可联系以及及时调整，名额被有意控制在少数。",
  "Platz anfragen": "咨询名额",
  "Dominik Dörfl beim Krafttraining im Studio": "Dominik Dörfl 在训练场进行力量训练",
  "12 WOCHEN": "12 周",
  "Premium-Coaching für Leistungsträger – nur wenige Plätze.": "面向高绩效人士的高端指导 —— 名额有限。",
  "Executive.": "高管。",
  "Performance.": "表现。",
  "In 12 Wochen.": "12 周之内。",
  "Das 12-Wochen-Premium-Programm für Führungskräfte, Unternehmer und Leistungsträger, die körperlich wieder klarer, fitter und belastbarer werden wollen.": "为希望重新变得更清醒、更有体能、更抗压的管理者、创业者与高绩效人士设计的 12 周高端计划。",
  "Analyse, Ernährungsführung, Training und App-Steuerung - abgestimmt auf einen vollen Kalender, hohe Verantwortung und einen echten Premium-Anspruch.": "测评、营养指导、训练与应用管理，全部按繁忙日程、重大责任与真正的高端标准来匹配。",
  "Eckdaten Executive Performance": "高管体能计划要点",
  "Wochen Programm": "周计划",
  "Persönliche Führung": "亲自指导",
  "Steuerung & Check-ins": "调控与阶段复查",
  "Für wen": "适合谁",
  "Gebaut für Menschen mit echter Verantwortung.": "为真正肩负责任的人而设。",
  "Executive Performance ist kein weiteres Fitnessangebot, sondern ein geführtes System für Leistungsträger, die ihren Körper wieder zu einem Vorteil machen wollen.": "高管体能计划不是又一个健身产品，而是一套有人带着走的体系，面向那些想让身体重新成为优势的人。",
  "Für volle Kalender": "为繁忙日程",
  "Verantwortung statt Freizeit": "责任在身，而非闲暇充裕",
  "Geschäftsführer, Selbstständige und Führungskräfte mit vollem Kalender, die nicht mehr Zeit, sondern ein klares System brauchen.": "日程排满的总经理、自由职业者与管理者，他们需要的不是更多时间，而是一套清晰的体系。",
  "Für echte Belastung": "为真实的压力",
  "Leistung im Alltag": "日常中的表现",
  "Menschen, die beruflich konstant performen müssen und körperlich wieder klarer, fitter und belastbarer werden wollen.": "必须在工作中持续输出，并希望身体重新变得清醒、有体能、抗压的人。",
  "Für Premium-Anspruch": "为高端标准",
  "Anspruch statt Standard": "有要求，而非将就",
  "Wer keine Massenlösung will, sondern persönliche Führung, messbare Werte und einen Plan, der sich an reale Prioritäten anpasst.": "不要批量方案，而要亲自指导、可测量的数据，以及能随真实优先级调整的计划。",
  "Ablauf": "流程",
  "So läuft dein 12-Wochen-Programm.": "你的 12 周计划怎么进行。",
  "Start mit 2D-Körperanalyse und InBody-Messung": "以 2D 体成分分析与 InBody 测量开始",
  "Zielgespräch für Körper, Alltag, Kalender und Prioritäten": "围绕身体、日常、日程与优先级的目标沟通",
  "Individuelle Ernährungs- und Trainingsplanung": "个性化的营养与训练规划",
  "Voller Zugang zur Camp Dörfl App": "完整的 Camp Dörfl 应用权限",
  "Wöchentliche Updates der Planung": "每周更新计划",
  "InBody-Messung alle vier Wochen": "每四周一次 InBody 测量",
  "Ein Personal Training pro Monat mit optionalen Zusatzterminen": "每月一次私教课，可另加课时",
  "Dominik Dörfl bei der Ernährungs- und Leistungsplanung": "Dominik Dörfl 在制定营养与表现计划",
  "Ergebnis": "结果",
  "Was nach 12 Wochen spürbar anders ist.": "12 周之后有什么明显不同。",
  "Ziel ist nicht ein kurzes Strohfeuer, sondern ein Zustand, den du in deinem Alltag und in deiner Leistungsfähigkeit wirklich merkst.": "目标不是昙花一现，而是一种你在日常与工作状态中真切感受得到的改变。",
  "Mehr Energie über den ganzen Tag": "全天更有精力",
  "Training, Ernährung und Routinen werden so gesteuert, dass Leistungsfähigkeit im Beruf und im Privaten spürbar steigt.": "训练、营养与作息被统一调控，让你在工作与生活中的状态明显提升。",
  "Sichtbare, messbare Entwicklung": "看得见、可衡量的变化",
  "InBody und 2D-Analyse machen Fortschritt in Zahlen sichtbar, statt ihn dem Gefühl oder dem Zufall zu überlassen.": "InBody 与 2D 分析把进步变成数字，而不是交给感觉或运气。",
  "Ein System, das im Alltag hält": "一套在日常中撑得住的体系",
  "Die Camp Dörfl App, wöchentliche Anpassungen und klare Führung sorgen dafür, dass der Plan auch in stressigen Wochen trägt.": "Camp Dörfl 应用、每周调整与明确的指导，让计划在最忙的一周里也能撑住。",
  "Warum Camp Dörfl": "为什么选 Camp Dörfl",
  "Geführt von echter Leistungserfahrung.": "由真实的竞技经验带队。",
  "Hinter dem Programm steht keine Theorie, sondern gelebte Praxis aus Leistungssport, Coaching und Unternehmertum – als Ex-Profi-Athlet, zweifacher Deutscher Meister und Coach von Top-Athleten.": "这个计划背后不是理论，而是来自竞技体育、指导工作与创业的亲身实践：前职业运动员、两届德国冠军，以及顶尖运动员的教练。",
  "Mehr über Dominik Dörfl": "了解更多关于 Dominik Dörfl",
  "Was Führungskräfte vor dem Start wissen wollen.": "管理者在开始前最想知道的事。",
  "Sichere dir einen der wenigen Plätze.": "抢下为数不多的名额之一。",
  "Wenn du beruflich viel leistest und körperlich wieder an deine echte Leistungsfähigkeit willst, ist eine kurze, ehrliche Anfrage der richtige Start.": "如果你在工作上付出很多，又希望身体回到真正的状态，一封简短而坦诚的咨询就是最好的开始。",
