  "Fitness App für Training, Ernährung, Check-ins, Coach-Zugang, GPS-Routen, Community und Fortschrittsanalyse.": "涵盖训练、营养、阶段记录、教练直连、GPS 路线、社群与进度分析的健身应用。",
  "Was ist die Fitness App von Camp Dörfl?": "Camp Dörfl 健身应用是什么？",
  "Die Camp Dörfl Fitness App bündelt Training, Ernährung, Check-ins, Scans, GPS-Routen, Community und Fortschrittsanalyse in einem persönlichen Performance-System.": "Camp Dörfl 健身应用把训练、营养、阶段记录、扫描识别、GPS 路线、社群与进度分析集中到一套属于你个人的运动表现体系中。",
  "Für wen eignet sich die Fitness App?": "这个健身应用适合谁？",
  "Für Menschen, die Training und Ernährung im Alltag klar strukturieren, Fortschritte nachvollziehen und bei Bedarf direkten Coach-Zugang nutzen möchten – eigenständig oder kombiniert mit Coaching.": "适合希望把训练与营养安排得井井有条、能追溯自己的进步，并在需要时直接联系教练的人，既可以独立使用，也可以搭配指导服务。",
  "Gibt es in der Fitness App Trainings- und Ernährungspläne?": "应用里有训练计划和营养计划吗？",
  "Ja. Individuelle Trainingsplanung, Ernährungsstruktur und die tägliche Umsetzung laufen in einer Oberfläche zusammen, statt über mehrere Tools verteilt zu sein.": "有。个性化训练规划、营养安排与每天的执行都在同一个界面里完成，不必分散在多个工具中。",
  "Wie starte ich mit der Camp Dörfl Fitness App?": "怎样开始使用 Camp Dörfl 健身应用？",
  "Der Einstieg beginnt mit einer kurzen Anfrage. Danach wird geklärt, ob reiner App-Zugang oder die Kombination mit Coaching sinnvoller ist und wie dein Setup aufgebaut wird.": "从一封简短的咨询开始。随后我们会确认单独使用应用还是搭配指导更合适，以及你的方案该怎么搭建。",
  "Was kostet der Zugang zur Fitness App?": "使用这个健身应用要多少钱？",
  "Das hängt davon ab, ob du die App eigenständig nutzen oder mit Coaching kombinieren willst. Im Erstkontakt wird geklärt, welches Modell zu deinem Ziel, deinem Alltag und deiner gewünschten Begleitung passt.": "这取决于你是单独使用应用，还是与指导服务结合。首次沟通时会确认哪种方案符合你的目标、日常与期望的陪伴程度。",
  "Welche Fitness-App-Funktionen helfen im Alltag besonders?": "哪些功能在日常中最有用？",
