  "Running Club, Cycling Club, Routen und Vergleiche verbinden digitale Struktur mit echter Bewegung und Motivation.": "跑步俱乐部、骑行俱乐部、路线与成绩对比，把数字化的结构与真实的运动和动力连在一起。",
