  "Der Code lautet Dominik und bringt 10 % Rabatt. Er wird bei XXL Nutrition im Warenkorb beziehungsweise an der Kasse in das Feld für Gutschein- und Rabattcodes eingetragen.": "优惠码是 Dominik，可享 10% 折扣。在 XXL Nutrition 的购物车或结算页面的优惠码输入框中填写即可。",
  "Wie löse ich den Rabattcode ein?": "怎样使用这个优惠码？",
  "Zuerst die Produkte in den Warenkorb legen, dann den Code Dominik im Gutscheinfeld eintragen und bestätigen. Vor dem Abschicken der Bestellung sollte der Abzug in der Summe sichtbar sein.": "先把商品加入购物车，再在优惠码输入框中填写 Dominik 并确认。提交订单前，应该能在总价中看到折扣。",
  "Kostet mich der Code etwas?": "使用优惠码要付费吗？",
  "Nein. Der Code ist kostenlos, an keine Bedingung von unserer Seite geknüpft und zieht 10 % von deiner Bestellung ab. Camp Dörfl ist Nutrition Partner von XXL Nutrition; über den Link kann eine Vergütung entstehen, für dich ändert sich am Preis dadurch nichts.": "不用。优惠码免费，我们这边不附加任何条件，可为您的订单减去 10%。Camp Dörfl 是 XXL Nutrition 的营养合作伙伴，通过该链接可能获得分成，但这不会改变您支付的价格。",
  "Für welche Produkte gilt der Code?": "优惠码适用于哪些商品？",
  "Umfang, Mindestbestellwert und mögliche Ausnahmen legt XXL Nutrition selbst fest und kann sie jederzeit ändern. Verbindlich ist immer das, was im Warenkorb angezeigt wird.": "适用范围、最低订单金额与可能的除外情况由 XXL Nutrition 自行规定，并可随时调整。以购物车中显示的结果为准。",
  "Was tun, wenn der Code nicht funktioniert?": "优惠码用不了怎么办？",
