  "Warum empfiehlt Dominik Dörfl XXL Nutrition?": "Dominik Dörfl 为什么推荐 XXL Nutrition？",
  "XXL Nutrition ist Nutrition Partner von Camp Dörfl. Die Zusammenarbeit läuft seit mehreren Jahren, die Produkte werden im eigenen Training und in der Betreuung eingesetzt.": "XXL Nutrition 是 Camp Dörfl 的营养合作伙伴。合作已持续多年，产品也用于他本人的训练与学员指导中。",
