  "Zwei Wege: die reine Messung mit deinen Werten — oder die Messung mit persönlicher Auswertung, in der die Zahlen für dein Ziel eingeordnet werden.": "两种选择：只做测量并拿到数据，或者测量加一对一解读，把数字放到你的目标里去看。",
