  "Vom Mannschaftssport über Titel im Kraftsport und extreme Ausdauerleistungen bis zu Coaching und Unternehmertum: Jede Station prägt, wie Camp Dörfl heute denkt.": "从团队运动，到力量项目的冠军头衔与极限耐力挑战，再到带教与创业：每一段经历都塑造了今天 Camp Dörfl 的思考方式。",
  "Fußball und frühe Leistungsumgebung": "足球与早期的竞技环境",
  "Dominik kommt aus dem Mannschaftssport. Auswahl-Niveau, klare Rollen, Drucksituationen und Training als fester Teil des Alltags prägen seinen Blick auf Leistung.": "Dominik 出身团队运动。代表队水平、明确分工、高压情境，以及把训练当成日常的一部分，塑造了他看待运动表现的方式。",
  "Aus Struktur wird Spezialisierung: Deutscher Meister im Bodybuilding, Deutscher Meister im Powerlifting und später IFBB Pro. Der Körper wird zum messbaren System.": "结构转化为专精：健美德国冠军、力量举德国冠军，之后成为 IFBB 职业选手。身体成了一个可以测量的系统。",
  "Ausdauer und extreme Umsetzung": "耐力与极限挑战",
  "Marathon, Halbmarathon, Triathlon, Ironman 70.3, 270 km Rad in 24 Stunden und 8848 Höhenmeter in 15 Stunden zeigen: Performance endet nicht an einer Sportart.": "马拉松、半程马拉松、铁人三项、Ironman 70.3、24 小时骑行 270 公里，以及 15 小时内累计爬升 8848 米，说明运动表现并不止于某一个项目。",
  "Coaching und Athletenentwicklung": "带教与运动员培养",
  "Dominik coacht Top-Athleten, Olympia-Athleten, deutsche Meister, Vize-Weltmeister und internationale Platzierungen. Der Anspruch bleibt: klare Systeme statt Zufall.": "Dominik 指导过顶尖运动员、奥运选手、德国冠军、世界亚军与多位国际赛事名次获得者。标准始终一致：靠清晰的体系，而不是靠运气。",
  "Unternehmertum und Community": "创业与社群",
  "Mit clever fit Nürnberg Süd und Camp Dörfl verbindet er physische Orte, digitale Begleitung und Community zu einem skalierbaren Performance-Ökosystem.": "通过 clever fit 纽伦堡南店与 Camp Dörfl，他把实体场地、数字陪伴与社群连成一个可扩展的运动表现生态。",
  "Leistungsspur": "成绩轨迹",
  "Erfahrung, die sich in Zahlen zeigt.": "用数字说话的经验。",
