  "Dominik Dörfl in Stichpunkten.": "Dominik Dörfl 要点速览。",
  "Unternehmer, Athlet, Coach, Moderator und Gründer von Camp Dörfl": "创业者、运动员、教练、活动主持人，Camp Dörfl 创始人",
