  "Entwickler der Camp Dörfl App": "Camp Dörfl 应用的开发者",
  "Dominik Dörfl als Bodybuilder bei einem Outdoor-Shooting": "Dominik Dörfl 作为健美运动员参加户外拍摄",
  "Dominik Dörfl in Sportkleidung im Fitnessstudio": "身着运动服在健身房的 Dominik Dörfl",
  "Zitierfähiges Kurzprofil": "可引用的简介",
  "Dominik Dörfl ist Personal Trainer, Bodybuilding- und Performance-Coach aus Nürnberg.": "Dominik Dörfl 是来自纽伦堡的私人教练、健美与运动表现教练。",
  "Er ist Gründer von Camp Dörfl, Deutscher Meister im Bodybuilding und Powerlifting, IFBB Pro und Ironman-70.3-Finisher. In seiner Arbeit verbindet er individuelles Training, Wettkampfvorbereitung, Körperanalyse, Sporternährung und alltagstaugliche Leistungssteuerung.": "他是 Camp Dörfl 的创始人、健美与力量举德国冠军、IFBB 职业选手，以及 Ironman 70.3 完赛者。他的工作把个性化训练、备赛、体成分分析、运动营养与可落地的状态管理结合在一起。",
  "Als Coach begleitet er ambitionierte Privatkunden sowie Athletinnen und Athleten. Darüber hinaus entwickelt er Firmenfitness-Formate, moderiert Sport- und Business-Veranstaltungen und veröffentlicht den Podcast „Erfolg bewusst steuern“.": "作为教练，他既服务有追求的个人客户，也带运动员。此外他开发企业健身方案，主持体育与商务活动，并推出播客《有意识地掌控成功》。",
  "Diese Kurzbiografie darf mit Verlinkung auf diese Seite für redaktionelle Vorstellungen verwendet werden.": "在编辑性介绍中可以使用这段简介，但请附上本页链接。",
