  "Die folgenden Seiten liegen außerhalb von campdoerfl.de und helfen dabei, Person, sportliche Ergebnisse und publizistische Arbeit eindeutig zuzuordnen.": "以下页面不属于 campdoerfl.de，可用于明确核实其身份、运动成绩与公开发表的内容。",
