  "Dieselbe Messung wie am Anfang. Aufgebaute Muskelmasse und veränderte Fettmasse stehen nebeneinander – nachprüfbar statt gefühlt.": "与开头相同的测量。增加的肌肉量与变化的脂肪量并列呈现，可核对，而不是凭感觉。",
