  "241 Titel in 10 Klassen": "10 个组别共 241 个冠军",
  "Alle aufklappen": "全部展开",
  "1965–2026 · 62 Titel": "1965–2026 · 62 个冠军",
  "Die Königsklasse und der eigentliche Mr.-Olympia-Titel: keine Gewichtsgrenze, bewertet wird die komplette Erscheinung aus Masse, Definition und Proportion.": "最高级别的组别，也是真正的奥林匹亚先生头衔：没有体重限制，评判的是围度、清晰度与比例构成的整体形象。",
  "Men’s Open beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Men’s Open 组，最新在前。",
  "Sieger": "冠军",
  "2008–2026 · 19 Titel": "2008–2026 · 19 个冠军",
  "zuletzt: Keone Pearson": "最近一位：Keone Pearson",
  "Für Athleten bis 212 Pfund (96,2 kg). 2008 bis 2011 lief die Klasse als „202 Showdown“ mit einer Grenze von 202 Pfund.": "面向体重不超过 212 磅（96.2 公斤）的选手。2008 至 2011 年该组别名为“202 Showdown”，上限为 202 磅。",
  "Men’s 212 beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Men’s 212 组，最新在前。",
  "2016–2026 · 11 Titel": "2016–2026 · 11 个冠军",
  "zuletzt: Niall Darwen": "最近一位：Niall Darwen",
  "Die Antwort auf den Ruf nach der goldenen Ära: Gewichtslimit nach Körpergröße, bewertet werden Linie und Taille statt maximaler Masse.": "对怀念黄金年代呼声的回应：按身高设定体重上限，评判线条与腰身，而非最大围度。",
  "2013–2026 · 14 Titel": "2013–2026 · 14 个冠军",
  "zuletzt: Ryan Terry": "最近一位：Ryan Terry",
  "Gewertet wird in Boardshorts, ohne Beinbewertung. Im Vordergrund stehen Oberkörper, Schulterbreite und Gesamteindruck.": "选手身着沙滩裤上场，不评判腿部。重点在上半身、肩宽与整体印象。",
  "Men’s Physique beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Men’s Physique 组，最新在前。",
  "1980–2026 · 42 Titel": "1980–2026 · 42 个冠军",
  "zuletzt: Andrea Shaw": "最近一位：Andrea Shaw",
  "Frauen-Bodybuilding, seit 1980. Zwischen 2015 und 2019 wurde der Titel nicht ausgetragen und kehrte 2020 zurück.": "女子健美，始于 1980 年。2015 至 2019 年间停办，2020 年回归。",
  "2015–2019: Der Titel wurde in diesen Jahren nicht ausgetragen.": "2015–2019：这几年该项目未曾举办。",
  "Ms. Olympia beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Ms. Olympia 组，最新在前。",
  "In diesem Jahr wurde in Gewichtsklassen gewertet, ohne Gesamtsiegerin.": "这一年按体重级别评分，未决出总冠军。",
  "1995–2026 · 32 Titel": "1995–2026 · 32 个冠军",
  "zuletzt: Michelle Fredua-Mensah": "最近一位：Michelle Fredua-Mensah",
  "Zwei Runden: eine Kür mit Kraft-, Beweglichkeits- und Turnelementen und eine Bewertung der Erscheinung.": "两轮比赛：一轮是包含力量、柔韧与体操动作的自选表演，一轮是形体评判。",
  "Fitness Olympia beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Fitness Olympia 组，最新在前。",
  "2003–2026 · 24 Titel": "2003–2026 · 24 个冠军",
  "zuletzt: Lola Montez": "最近一位：Lola Montez",
  "Athletische Linie mit betonter V-Form, weniger Masse als im Frauen-Bodybuilding und mehr als in der Bikini-Klasse.": "强调 V 形的运动线条，围度小于女子健美，大于 Bikini 组。",
  "Figure Olympia beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Figure Olympia 组，最新在前。",
  "2010–2026 · 17 Titel": "2010–2026 · 17 个冠军",
  "zuletzt: Jasmine Gonzalez": "最近一位：Jasmine Gonzalez",
  "Die jüngste und größte Frauenklasse: Bewertet werden Gesamtbild, Proportion und Bühnenpräsenz, nicht die Muskelmasse.": "最年轻也最庞大的女子组别：评判整体形象、比例与舞台表现力，而非肌肉量。",
  "Bikini Olympia beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Bikini Olympia 组，最新在前。",
  "zuletzt: Natalia Abraham Coelho": "最近一位：Natalia Abraham Coelho",
  "Zwischen Figure und Frauen-Bodybuilding: mehr Muskel als in der Figure-Klasse, gewertet mit Pflichtposen.": "介于 Figure 与女子健美之间：肌肉量多于 Figure 组，以规定造型评分。",
  "Women’s Physique beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Women’s Physique 组，最新在前。",
  "2021–2026 · 6 Titel": "2021–2026 · 6 个冠军",
  "zuletzt: Eduarda Bezerra": "最近一位：Eduarda Bezerra",
  "2021 eingeführt: kräftigere Beine und Gesäßmuskulatur im Verhältnis zum Oberkörper, ursprünglich aus Brasilien kommend.": "2021 年设立：相对上半身而言，腿部与臀部更为发达，最初源自巴西。",
  "Wellness Olympia beim Mr. Olympia — neueste zuerst.": "奥林匹亚先生 Wellness Olympia 组，最新在前。",
  "Kein Treffer. Prüfe die Schreibweise oder setze die Filter zurück.": "没有结果。请检查拼写或重置筛选。",
  "Rekorde": "纪录",
  "Wer am häufigsten gewonnen hat.": "谁夺冠次数最多。",
  "Gezählt werden Titel, nicht Teilnahmen. Links die Königsklasse, rechts alle erfassten Klassen zusammen.": "统计的是冠军数，而非参赛次数。左侧为最高级别组别，右侧为所有已收录组别的合计。",
  "Sechs Jahrzehnte in vier Schritten.": "六十年，四个阶段。",
  "1965–1979: die Gründerjahre": "1965–1979：草创年代",
  "Larry Scott gewinnt die ersten beiden Titel, Sergio Oliva und Arnold Schwarzenegger prägen die Siebziger. Arnold holt bis 1975 sechs Titel in Folge.": "Larry Scott 拿下最初两个冠军，Sergio Oliva 与 Arnold Schwarzenegger 定义了七十年代。Arnold 到 1975 年为止六连冠。",
  "1980–1997: Ordnung und Dominanz": "1980–1997：秩序与统治",
  "Nach Arnolds umstrittenem Comeback 1980 folgen die langen Regentschaften: Lee Haney acht Titel, danach Dorian Yates sechs. Die Bühne wird professioneller, die Athleten schwerer.": "在 Arnold 于 1980 年引发争议的复出之后，是漫长的统治期：Lee Haney 八冠，随后 Dorian Yates 六冠。舞台愈发专业，选手也愈发厚重。",
  "1998–2017: die Massenära": "1998–2017：围度年代",
  "Ronnie Coleman stellt mit acht Titeln Haneys Rekord ein, Jay Cutler unterbricht ihn zweimal, Phil Heath gewinnt sieben Mal in Folge. Gleichzeitig entstehen 212, Figure und Bikini.": "Ronnie Coleman 以八冠追平 Haney 的纪录，Jay Cutler 两度将其打断，Phil Heath 七连冠。与此同时，212、Figure 和 Bikini 组别相继设立。",
  "Seit 2018: offener denn je": "2018 年至今：前所未有的开放",
  "Sieben verschiedene Namen in neun Jahren in der offenen Klasse. Parallel wächst das Feld: Classic Physique und Wellness ziehen ein neues Publikum an.": "九年之内，公开组出现七个不同的冠军名字。参赛阵容同时扩大：Classic Physique 与 Wellness 吸引了新的观众。",
  "Häufige Fragen zum Mr. Olympia.": "关于奥林匹亚先生的常见问题。",
  "Vom Zuschauen zum Antreten": "从看台走上舞台",
  "Wettkampf ist planbar.": "比赛是可以规划的。",
  "Wer selbst auf eine Bühne will, braucht keinen Zufall, sondern einen Plan aus Aufbau, Diät und Peak Week. Genau daran arbeite ich mit meinen Athleten.": "想要自己站上舞台，靠的不是运气，而是一套由增肌期、减脂期和赛前一周组成的计划。我和我的运动员做的正是这件事。",
  "Wettkampfcoaching ansehen": "查看备赛指导",
  "Wettkämpfe 2026": "2026 年赛事",

