  "Dominik Dörfl als Moderator auf einer Eventbühne mit Publikum": "Dominik Dörfl 在有观众的活动舞台上担任主持",
  "Events · Moderation · Hosting": "活动 · 主持 · 串场",
  "Moderator in Nürnberg für Interviews, Panels, Eröffnungen und Bühnenformate mit sportlicher Präsenz, sauberer Dramaturgie und professioneller Ruhe.": "纽伦堡的活动主持人，承接访谈、论坛、开幕与各类舞台形式，兼具运动员般的气场、清晰的节目走向与专业的从容。",
  "Besonders stark, wenn Markenwirkung, Timing und sichere Gesprächsführung gleichzeitig zählen.": "当品牌效果、节奏把控与稳健的对谈同时重要时，尤其见功力。",
