  "Dominik Dörfl als Moderator mit Mikrofon auf einer Bühne": "Dominik Dörfl 手持话筒在舞台上主持",
  "Events im Einsatz.": "活动现场实录。",
  "Interview-Beispiel": "访谈示例",
  "Interviews ruhig, präsent und professionell führen.": "沉稳、在场、专业地把访谈带下去。",
  "Gerade im Gespräch zeigt sich, ob ein Moderator nur Fragen stellt oder einen Gast wirklich sicher durch den Moment führt. So entsteht eine Bühne, auf der Menschen kompetent wirken und Ihre Veranstaltung hochwertig getragen wird.": "一场对谈最能看出，一个主持人只是在提问，还是真的能稳稳把嘉宾带过每一个瞬间。这样才有一个让人显得专业的舞台，让您的活动被有分量地托住。",
  "Gespräche mit Haltung": "有分寸的对谈",
  "Fragen, Übergänge und Reaktionen bleiben klar, nahbar und souverän, ohne künstlich oder überladen zu wirken.": "提问、衔接与回应始终清晰、亲切、自如，不刻意也不冗余。",
  "Stark für Gäste und Publikum": "对嘉宾和观众都有力",
  "Ideal für Bühneninterviews, Talk-Momente und Einbindungen, bei denen Präsenz, Sicherheit und Vertrauen direkt sichtbar werden sollen.": "适合舞台访谈、对谈环节与观众互动，让临场感、稳健与信任直接被看见。",
