  "Welche Bühnenformate Camp&nbsp;Dörfl besonders stark trägt.": "Camp&nbsp;Dörfl 尤其擅长托住哪些舞台形式。",
  "Für Veranstalter, die einen Moderator suchen, der Ablauf, Publikum und Marke nicht nur zusammenbringt, sondern sichtbar aufwertet.": "适合这样的主办方：他们要找的主持人不只把流程、观众与品牌串到一起，还能让整体明显提档。",
