  // ============================================================
  // Bodybuilding-Coaching + BIA-Rest
  // ============================================================
  "InBody BIA-Messung": "InBody 生物电阻抗测量",
  "Die Bioelektrische Impedanzanalyse – kurz BIA – dient zur Einordnung der Körperzusammensetzung, etwa von Muskelmasse, Körperfettanteil und Körperwasser.": "生物电阻抗分析（简称 BIA）用于判断身体成分，例如肌肉量、体脂率和体内水分。",
  "Bodybuilding Coach Nürnberg & Online | Wettkampfvorbereitung": "纽伦堡与线上健美教练 | 备赛指导",
  "Bodybuilding Coaching und Wettkampfvorbereitung mit IFBB Pro Dominik Dörfl: vor Ort in Nürnberg oder online. Für Newcomer, aktive Athleten und Coach-Wechsel.": "与 IFBB 职业选手 Dominik Dörfl 一起进行健美指导与备赛：可在纽伦堡当面进行，也可线上进行。适合新手、在役选手以及更换教练者。",
  "Bodybuilding Coach Dominik Dörfl auf der Wettkampfbühne": "健美教练 Dominik Dörfl 在比赛舞台上",
  "Bodybuilding Coaching und Wettkampfvorbereitung": "健美指导与备赛",
  "Individuelle Wettkampfvorbereitung für Newcomer und erfahrene Athleten vor Ort in Nürnberg sowie online.": "为新手与资深选手量身定制的备赛方案，可在纽伦堡当面进行，也可线上进行。",
  "Ist das Bodybuilding Coaching auch für meinen ersten Wettkampf geeignet?": "健美指导也适合我的第一场比赛吗？",
  "Ja. Gerade beim ersten Start schafft eine frühe Einordnung von Verband, Klasse, Ausgangsform und realistischem Zeitfenster Sicherheit. Training, Ernährung, Check-ins, Posing und Peak Week werden zu einem nachvollziehbaren Gesamtplan.": "适合。尤其是首次登台，早早理清协会、组别、起点状态与合理的时间窗，会让人心里有底。训练、饮食、阶段回访、造型与赛前一周会整合成一份看得懂的完整计划。",
  "Kann ich zu Dominik wechseln, obwohl meine Vorbereitung bereits läuft?": "备赛已经开始了，还能换到 Dominik 这里吗？",
  "Ja, sofern noch Kapazität besteht und ein Wechsel fachlich sinnvoll ist. Im ersten Check werden aktueller Plan, Form, Zeit bis zur Show, bisheriger Verlauf und offene Probleme ehrlich bewertet.": "可以，前提是还有名额，并且从专业角度看更换教练确实合理。第一次评估会如实分析当前计划、状态、距离比赛的时间、此前的进展和尚未解决的问题。",
  "Funktioniert die Wettkampfvorbereitung komplett online?": "备赛可以完全在线上进行吗？",
  "Ja. Das Online Coaching ist deutschlandweit und international möglich. Fortschrittsbilder, Trainingsdaten, Körperwerte, Ernährungsumsetzung und regelmäßige Check-ins bilden die Grundlage für laufende Anpassungen.": "可以。线上指导覆盖德国全境，也接受国际学员。进度照片、训练数据、身体指标、饮食执行情况和定期回访构成持续调整的依据。",
  "Wo findet das Bodybuilding Coaching vor Ort statt?": "当面的健美指导在哪里进行？",
  "Die persönliche Betreuung findet in Nürnberg statt. Formchecks, Training, Posing und Körperanalyse können vor Ort mit der digitalen Begleitung verbunden werden.": "当面的陪伴在纽伦堡进行。状态检查、训练、造型和身体成分分析可以在现场完成，并与线上跟进结合起来。",
  "Wie früh sollte eine Wettkampfvorbereitung beginnen?": "备赛应该提前多久开始？",
  "Das hängt von Ausgangsform, Muskelmasse, Klasse, Wettkampferfahrung und Show-Termin ab. Eine gute Vorbereitung beginnt dann, wenn das Ziel mit vertretbarem Tempo und genügend Reserven erreichbar ist.": "这取决于起点状态、肌肉量、组别、参赛经验和比赛日期。好的备赛开始于这样一个时点：以稳妥的节奏、留有余量地就能达成目标。",
  "Ist das Coaching nur für Profi-Athleten?": "这项指导只面向职业选手吗？",
  "Nein. Entscheidend sind Ernsthaftigkeit, Verlässlichkeit und die Bereitschaft, Feedback umzusetzen. Dominik begleitet ambitionierte Newcomer ebenso wie erfahrene Athleten.": "不是。关键在于认真、可靠，以及愿意把反馈落到实处。Dominik 既带有志气的新手，也带经验丰富的选手。",
  "Bodybuilding Coach Dominik Dörfl in Wettkampfform auf der Bühne": "健美教练 Dominik Dörfl 以参赛状态站在舞台上",
