  "Eine gute Vorbereitung beginnt mit einer ehrlichen Standortbestimmung – nicht mit einem Standardplan oder dem Versprechen, dass jede Show die richtige ist.": "好的备赛始于一次诚实的现状判断，而不是一份通用计划，也不是“哪场比赛都合适”的承诺。",
