  "Pläne kommen zu spät, Anpassungen sind nicht nachvollziehbar oder du drehst dich trotz Disziplin im Kreis. Dann braucht es zuerst einen sauberen Audit.": "计划来得太迟，调整讲不出道理，或者你明明很自律却在原地打转。那就先做一次干净的复盘。",
