  "Ich war selbst Profi-Athlet auf europäischem Spitzenlevel, bin IFBB Pro und Deutscher Meister im Bodybuilding. Heute verbinde ich diese eigene Bühnenerfahrung mit der Verantwortung als Coach.": "我本人曾是欧洲顶级水平的职业选手，是 IFBB 职业选手，也是德国健美冠军。如今我把这份亲身的舞台经验和作为教练的责任结合在一起。",
