  "Eine Wettkampfvorbereitung dauert in der Regel 16 bis 24 Wochen. Wie lang sie im Einzelfall angesetzt wird, hängt von Ausgangsform, Klasse und Show-Termin ab.": "备赛通常持续 16 到 24 周。具体安排多长，取决于起始状态、组别和比赛日期。",
