  // ============================================================
  // Personal Trainer Nürnberg
  // ============================================================
  "Personal Trainer Nürnberg | 1:1 Coaching · Dominik Dörfl": "纽伦堡私人教练 | 一对一指导 · Dominik Dörfl",
  "Personal Trainer in Nürnberg für Abnehmen, Kraft und mehr Energie im Alltag: 1:1 Training, Körperanalyse und Ernährung, persönlich geführt von Dominik Dörfl.": "纽伦堡的私人教练，帮你减脂、增力、恢复日常精力：一对一训练、身体成分分析与饮食安排，由 Dominik Dörfl 亲自带教。",
  "Dominik Dörfl, Personal Trainer in Nürnberg, beim Zieleinlauf im Ironman-Trikot": "纽伦堡私人教练 Dominik Dörfl 身着铁人三项队服冲过终点",
  "Personal Trainer Nürnberg – Camp Dörfl": "纽伦堡私人教练 – Camp Dörfl",
  "Persönlich geführtes 1:1 Personal Training in Nürnberg für Abnehmen, Kraftaufbau und mehr Energie im Alltag — mit Körperanalyse, Ernährungsplanung und laufender Anpassung.": "纽伦堡的一对一私教课程，由本人亲自带教，目标是减脂、增力和恢复日常精力，配有身体成分分析、饮食规划与持续调整。",
  "Personal Trainer in Nürnberg": "纽伦堡的私人教练",
  "Ist Personal Training in Nürnberg auch für Einsteiger geeignet?": "纽伦堡的私教课程也适合初学者吗？",
  "Ja. Ein großer Teil der Zusammenarbeit beginnt ohne Trainingserfahrung. Übungsauswahl, Umfang und Tempo richten sich nach deiner Ausgangslage — Vorkenntnisse sind keine Voraussetzung, sondern das Ergebnis der ersten Wochen.": "适合。很多合作都是从零训练经验开始的。动作选择、训练量与推进速度都按你的起点来定。基础不是前提，而是最初几周的成果。",
  "Kann ich mit Personal Training in Nürnberg abnehmen?": "在纽伦堡上私教课能减脂吗？",
  "Ja. Grundlage sind eine Körperanalyse zu Beginn, ein Ernährungsrahmen, der zu deinem Alltag passt, und ein Training, das Muskulatur erhält. Die Entwicklung wird regelmäßig gemessen statt geschätzt.": "可以。基础是开始时的身体成分分析、一套贴合你日常的饮食框架，以及能保住肌肉的训练。进展靠定期测量，而不是靠估计。",
  "Wie oft trainieren wir pro Woche?": "我们每周训练几次？",
  "Das hängt von Ziel, Kalender und Belastbarkeit ab. Manche trainieren einmal pro Woche gemeinsam und den Rest eigenständig nach Plan, andere häufiger. Der Rahmen wird im Erstgespräch festgelegt.": "这取决于目标、日程和承受能力。有人每周和我一起练一次，其余按计划自己完成，也有人练得更频繁。具体安排在首次沟通时确定。",
  "Für wen ist Personal Training in Nürnberg bei Camp Dörfl gedacht?": "Camp Dörfl 在纽伦堡的私教课适合谁？",
  "Für Menschen in Nürnberg, die nicht nur trainieren, sondern mit klarer persönlicher Führung, Ernährungsstruktur und messbaren Fortschritten an ihrem Ziel arbeiten möchten – auch bei einem vollen Kalender.": "适合纽伦堡这样一群人：他们不只想练，更想在明确的个人带教、饮食结构和可衡量的进展中朝目标推进，哪怕日程已经很满。",
  "Was kostet Personal Training oder Premium Personal Training?": "私教课和高端私教课多少钱？",
  "Eine Einzelsession kostet 120 Euro; inklusive 2D-Körperanalyse sind es 150 Euro. Die 5er-Karte kostet 500 Euro, die 10er-Karte 800 Euro und die Premium Begleitung startet ab 200 Euro monatlich. Alle Details findest du in der Preisübersicht.": "单次课程 120 欧元，含 2D 身体成分分析为 150 欧元。5 次卡 500 欧元，10 次卡 800 欧元，高端陪伴服务每月 200 欧元起。全部细节见价格一览。",
  "Wie startet Personal Training in Nürnberg bei Camp Dörfl?": "在 Camp Dörfl 开始纽伦堡的私教课要怎么做？",
  "Der Start beginnt mit einer persönlichen Einordnung deiner Ausgangslage und Ziele. Danach folgen 2D-Körperanalyse, InBody, ein individueller Trainings- und Ernährungsplan, App-Zugang und die laufende Anpassung im Alltag.": "先当面理清你的起点和目标。随后是 2D 身体成分分析、InBody 测量、一份个性化的训练与饮食计划、应用权限，以及在日常中的持续调整。",
  "Passt das Training auch bei wenig Zeit und vollem Kalender?": "时间少、日程满，这样的训练还合适吗？",
  "Ja. Genau dafür ist das System gemacht. Es richtet sich an Menschen mit Verantwortung, vollen Wochen und wenig Lust auf starre Fitness-Pläne, die am echten Alltag vorbeigehen.": "合适。这套体系就是为此而设的。它面向那些肩上有责任、一周排得很满、又不想要脱离现实的死板健身计划的人。",
  "Wie exklusiv ist die Betreuung?": "带教有多专属？",
  "Bewusst exklusiv. Es geht nicht um Masse, sondern um persönliche Führung, direkte Anpassung und einen Rahmen, in dem echte Entwicklung möglich wird.": "刻意保持专属。重点不在数量，而在于亲自带教、即时调整，以及一个真正能带来进步的框架。",
  "Was macht das Training anders als Standardprogramme?": "这样的训练和通用课程有什么不同？",
  "Es plant echte Wochen mit ein. Training, Ernährung, Alltagsbelastung, Personal Trainings und Analysen werden auf deinen Kalender abgestimmt.": "它把真实的一周算进去。训练、饮食、日常负荷、私教课与各项分析都按你的日程来安排。",
  "Wo findet das Personal Training in Nürnberg statt?": "纽伦堡的私教课在哪里进行？",
  "Der persönliche Ausgangspunkt ist Camp Dörfl in Nürnberg. Je nach Ziel und vereinbartem Format werden Training, Analyse und Beratung passend geplant; auch Anfragen aus Fürth und Erlangen sind möglich.": "起点是纽伦堡的 Camp Dörfl。训练、分析与咨询会按目标和约定的形式来安排，来自菲尔特和埃尔朗根的咨询同样欢迎。",
