  "Wie teuer ist ein Personal Trainer in Nürnberg?": "在纽伦堡请私人教练要花多少钱？",
  "Bei Camp Dörfl kostet eine einzelne Personal-Training-Session 120 Euro; inklusive 2D-Körperanalyse sind es 150 Euro. Mit der 5er-Karte liegt eine Session bei 100 Euro, mit der 10er-Karte bei 80 Euro. Der digitale Einstieg über die Camp Dörfl App kostet 9,99 Euro monatlich. Die Premium Begleitung startet ab 200 Euro monatlich.": "在 Camp Dörfl，单次私教课 120 欧元，含 2D 身体成分分析为 150 欧元。用 5 次卡每节 100 欧元，用 10 次卡每节 80 欧元。通过 Camp Dörfl 应用入门每月 9.99 欧元。高端陪伴每月 200 欧元起。",
  "Was kostet Personal Training pro Stunde?": "私教课每小时多少钱？",
  "Eine Einzelsession kostet 120 Euro ohne oder 150 Euro inklusive 2D-Körperanalyse. Bei einer 5er-Karte reduziert sich der Preis auf 100 Euro pro Session, bei einer 10er-Karte auf 80 Euro pro Session.": "单次课程不含 2D 身体成分分析为 120 欧元，含则为 150 欧元。购买 5 次卡后每节降至 100 欧元，10 次卡则为每节 80 欧元。",
  "Lohnt sich Personal Training?": "私教课值得吗？",
  "Personal Training lohnt sich besonders, wenn du Fehler und Umwege vermeiden, Übungen sicher ausführen und dein Training konsequent an Ziel, Alltag und Ausgangslage anpassen möchtest. Entscheidend ist nicht nur die Stunde selbst, sondern wie gut du das Gelernte zwischen den Terminen umsetzen kannst.": "如果你想少走弯路、把动作做安全，并让训练始终贴合目标、日常和自身状况，私教课尤其值得。关键不只是这一节课本身，还有你在课与课之间能把学到的东西落实到什么程度。",
  "Wie oft sollte man Personal Training buchen?": "私教课应该多久上一次？",
  "Das hängt von Erfahrung, Ziel und gewünschter Eigenständigkeit ab. Für einen Technik-Check kann ein Einzeltermin reichen. Für neue Routinen und kontinuierlichen Fortschritt sind mehrere aufeinander aufbauende Sessions oder eine laufende Begleitung meist sinnvoller.": "这取决于经验、目标以及你希望多大程度上自己练。只做动作检查，一次课通常就够。想建立新习惯并持续进步，多节递进的课程或持续陪伴通常更合适。",
  "Gibt es eine Probestunde ohne Kartenbindung?": "有不绑定次卡的体验课吗？",
  "Der flexible Einstieg ist eine einzelne Session ohne Kartenbindung. So kannst du einen konkreten Trainingsimpuls, Technik-Feedback oder eine persönliche Standortbestimmung buchen, bevor du dich für mehrere Termine entscheidest.": "最灵活的方式就是不绑定次卡的单次课程。你可以先约一次，获得具体的训练刺激、动作反馈或一次现状评估，再决定要不要多约几次。",
  "Wann lohnt sich die Premium Begleitung?": "什么情况下值得选高端陪伴？",
  "Vor allem dann, wenn du Training, Ernährung, Analyse, App und laufende Anpassung als zusammenhängendes System brauchst. Der konkrete Umfang wird passend zu Ziel, Alltag und gewünschter Betreuungstiefe vereinbart.": "尤其是当你需要把训练、饮食、分析、应用与持续调整当作一个整体来用的时候。具体范围会按目标、日常和你希望的带教深度来约定。",
  "Dominik Dörfl beim Personal Training mit einem Kunden im Studio": "Dominik Dörfl 在健身房为一位客户上私教课",
  "Personal Trainer Nürnberg · Preise transparent": "纽伦堡私人教练 · 价格透明",
  "Sechs Wege, von 9,99 Euro im Monat für den App-Zugang über Einzelsession, Karten und Online Coaching bis zur Premium Begleitung ab 200 Euro monatlich. Hier siehst du auf einen Blick, welches Modell zu deinem Ziel und deinem Alltag passt.": "六种方式：从每月 9.99 欧元的应用权限，到单次课程、次卡和线上指导，再到每月 200 欧元起的高端陪伴。哪种方案贴合你的目标与日常，这里一目了然。",
  "Transparent vergleichen, passend entscheiden und direkt mit Dominik klären, welcher Einstieg wirklich sinnvoll ist.": "透明比较、选出合适的那一种，并直接和 Dominik 确认哪种入门方式真的说得通。",
