  "Die sinnvollste Frage ist meist nicht nur, was eine Stunde kostet, sondern welches Format realen Fortschritt bei dir überhaupt möglich macht.": "更值得问的往往不只是一节课多少钱，而是哪种形式才真的能让你取得进步。",
