  "Status vor Start": "开始前的状态",
  "Wenn Analyse, InBody, 2D-Technik oder eine saubere Trainings- und Ernährungsplanung dazugehören sollen, steigt auch die Tiefe der Betreuung.": "如果还要加上分析、InBody 测量、2D 技术评估或一份完整的训练与饮食规划，带教的深度自然也随之增加。",
