  "Firmenfitness Nürnberg & deutschlandweit | Camp Dörfl": "纽伦堡及德国全境的企业健康服务 | Camp Dörfl",
  "Firmenfitness aus Nürnberg, deutschlandweit: Gesundheitstage mit InBody, persönliche Beratung, Ernährungsvorträge und Team-Aktivierung für Unternehmen.": "来自纽伦堡、服务德国全境的企业健康方案：含 InBody 测量的健康日、一对一咨询、营养讲座与团队激活。",
  "Dominik Dörfl bei einer Firmenfitness-Analyse und Beratung": "Dominik Dörfl 在企业健康服务中进行分析与咨询",
  "Firmenfitness Nürnberg & deutschlandweit": "纽伦堡及德国全境的企业健康服务",
  "Firmenfitness deutschlandweit – Camp Dörfl": "覆盖德国全境的企业健康服务 – Camp Dörfl",
  "Deutschlandweite Gesundheitstage mit InBody-Körperanalyse und Beratung, berufsfeldbezogene Ernährungsvorträge sowie Bewegungs- und Team-Aktivierungen für Unternehmen.": "面向企业、覆盖德国全境的健康日，含 InBody 身体成分分析与咨询、贴合岗位的营养讲座，以及运动与团队激活活动。",
  "Für welche Unternehmen ist Firmenfitness sinnvoll?": "哪些企业适合做企业健康服务？",
  "Für Unternehmen, die Gesundheitstage, Performance-Impulse oder hochwertige Gesundheitskommunikation mit echter Substanz umsetzen wollen.": "适合那些希望举办健康日、注入状态提升的动力，或开展有真材实料的高质量健康沟通的企业。",
  "Was kostet Firmenfitness oder ein Gesundheitstag?": "企业健康服务或一场健康日要多少钱？",
  "Der Aufwand richtet sich nach Teamgröße, Modulen, Dauer und gewünschter Betreuung vor Ort. Nach einer kurzen Anfrage lässt sich schnell einschätzen, welches Format fachlich und wirtschaftlich sinnvoll ist.": "投入取决于团队规模、所选模块、时长以及现场需要的服务程度。简单咨询之后，就能很快判断哪种形式在专业与成本上都说得通。",
  "Welche drei Firmenfitness-Angebote gibt es?": "企业健康服务有哪三种？",
  "Camp Dörfl bietet Gesundheitstage mit InBody-Körperanalyse und Beratung, berufsfeldbezogene Ernährungsvorträge sowie aktive Bewegungs- und Teamimpulse an. Die Formate können einzeln gebucht oder sinnvoll kombiniert werden.": "Camp Dörfl 提供三项服务：含 InBody 身体成分分析与咨询的健康日、贴合岗位的营养讲座，以及运动与团队激活活动。三者可单独预约，也可合理组合。",
  "Wie läuft ein Gesundheitstag mit Camp Dörfl ab?": "Camp Dörfl 的健康日是怎么进行的？",
  "Die Teilnehmenden werden mit InBody und auf Wunsch mit ergänzender 2D-Technik analysiert. Direkt danach folgt eine persönliche, verständliche Beratung mit konkreten Empfehlungen für Ernährung, Bewegung und gesundheitsfördernde Routinen.": "参与者会接受 InBody 测量，如有需要还可加做 2D 技术分析。随后立即进行一对一、易懂的咨询，给出关于饮食、运动和促进健康的日常习惯的具体建议。",
  "Für wie viele Mitarbeitende kann Firmenfitness geplant werden?": "企业健康服务能安排多少名员工？",
  "Sowohl kleinere Teams als auch größere Gesundheitstage sind möglich. Die Organisation wird so geplant, dass Teilnehmerzahl, Taktung und Beratungsqualität zusammenpassen.": "小团队和大型健康日都可以。组织安排会让人数、节奏与咨询质量彼此匹配。",
  "Wird der Ernährungsvortrag an das Berufsfeld angepasst?": "营养讲座会按岗位调整吗？",
  "Ja. Der Vortrag ‚Warum Dranbleiben für unsere Gesundheit kein Nice-to-have ist‘ wird auf Arbeitsrealität, Schichtmodell, Büroalltag, körperliche Belastung oder Führungsverantwortung zugeschnitten. Ernährung und Sportintegration werden dadurch konkret statt allgemein.": "会。讲座《为什么坚持对我们的健康不是可有可无》会依据实际工作情况、轮班制度、办公室日常、体力负荷或管理责任来量身调整。这样一来，饮食与运动的融入就变得具体，而不是泛泛而谈。",
  "Wie viel Abstimmung braucht das intern im Unternehmen?": "企业内部需要做多少协调？",
  "So wenig wie möglich und so viel wie nötig. Camp Dörfl hilft dabei, Organisation, Kommunikation und Durchführung klar zu strukturieren, damit das Format intern leicht organisierbar bleibt.": "能少则少，该有的不缺。Camp Dörfl 会帮忙把组织、沟通与执行理出清晰的结构，让整个活动在内部容易安排。",
  "Wo bietet Camp Dörfl Firmenfitness an?": "Camp Dörfl 在哪些地方提供企业健康服务？",
  "Camp Dörfl hat seinen Ausgangspunkt in Nürnberg und bietet Gesundheitstage, Vorträge und Team-Aktivierungen deutschlandweit direkt in Unternehmen und öffentlichen Einrichtungen an.": "Camp Dörfl 以纽伦堡为起点，在德国全境的企业与公共机构现场提供健康日、讲座与团队激活活动。",
