  "Gesundheit wird dann relevant, wenn Mitarbeitende verstehen, was sie konkret tun können. Deshalb verbindet jedes Angebot fachliche Substanz mit einer Umsetzung, die zum jeweiligen Berufsfeld passt.": "只有当员工明白自己具体能做什么时，健康才真正与他们相关。因此每项服务都把专业内容与贴合各自岗位的执行方式结合起来。",
