  "Alle Preise sind Endpreise. Versand 4,90 € für Kleidung, 2,90 € für Gutscheine — pro Bestellung, nicht je Stück. Verbindlich wird die Bestellung erst mit meiner Bestätigung.": "所有价格均为最终价格。服饰运费 €4.90，礼券运费 €2.90，按订单计算，而非按件计算。订单只有在我确认之后才具有约束力。",
