  "Acht Shirts, ein Sweatshirt, zwei Jacken, ein Bär, ein Beutel, ein Emblem: Camp Dörfl #MEMBER und darunter": "八件 T 恤、一件卫衣、两件外套、一只小熊、一个束口袋，一个徽标：Camp Dörfl #MEMBER，下面写着",
  "NO TIME TO BE LAZY": "NO TIME TO BE LAZY",
  ". Dazu Gutscheine für Training, Körperanalyse und Online Coaching. Ausgesucht wird hier — gekauft wird nicht. Du stellst deine Auswahl zusammen und schickst sie mir als Vorbestellung.": "。此外还有用于训练、身体成分分析和线上指导的礼券。这里只挑选，不付款。你把想要的选好，作为预订发给我。",
  "Kollektion ansehen": "查看系列",
  "Vorbestellung": "预订",
  "je Shirt": "每件 T 恤",
  "je Sweatshirt": "每件卫衣",
