  "je Gutschein": "每张礼券",
  "So läuft es ab": "流程是这样的",
  "Vorbestellen dann bezahlen.": "先预订，后付款。",
  "Es gibt keinen Warenkorb und keine Kasse. Drei Schritte, dazwischen eine persönliche Rückmeldung von mir.": "这里没有购物车，也没有收银台。三个步骤，中间是我本人的一次回复。",
  "Auswählen": "挑选",
  "Farbe und Größe wählen, auf „Vorbestellen“ tippen. Die Auswahl sammelt sich in der Übersicht — Summe und Versand stehen sofort dabei.": "选好颜色和尺码，点“预订”。所选内容会汇总在概览里，金额与运费随即显示。",
  "Anfrage abschicken": "提交申请",
  "Adresse eintragen und absenden. Deine Vorbestellung kommt als E-Mail bei mir an. Bezahlt wird an dieser Stelle nichts.": "填好地址并提交。你的预订会以邮件形式到我这里。这一步不需要付款。",
  "Bestätigung abwarten": "等待确认",
  "Du bekommst eine persönliche Rückmeldung mit Verfügbarkeit, Summe und Zahlungsweg. Erst damit wird die Bestellung verbindlich.": "你会收到我本人的回复，说明库存情况、总金额与付款方式。到这时订单才具有约束力。",
  "Schritt 02": "第 02 步",
