  "Stand": "信息截至",
  "September 2026": "2026 年 9 月",
  "Der aktuelle XXL Nutrition Rabattcode lautet DOMINIK und bringt 10 % auf deine Bestellung. Camp Dörfl ist Nutrition Partner von XXL Nutrition — der Code kostet nichts und ist an keine Bedingung von unserer Seite geknüpft. Darunter steht, wie du ihn einlöst und wofür er gilt.": "当前的 XXL Nutrition 优惠码是 DOMINIK，可为你的订单减免 10%。Camp Dörfl 是 XXL Nutrition 的 Nutrition Partner —— 这个码不收费，我们这边也不附带任何条件。下面写明怎么使用，以及适用范围。",
  "Der Ablauf dauert keine Minute. Wichtig ist nur die Reihenfolge: erst der Warenkorb, dann der Code, dann der Blick auf die Summe.": "整个过程用不了一分钟。重要的只是顺序：先放购物车，再输入优惠码，然后看一眼总额。",
  "Code DOMINIK eintragen": "输入优惠码 DOMINIK",
  "Im Warenkorb beziehungsweise an der Kasse gibt es ein Feld für Gutschein- oder Rabattcodes. Dort den Code eintragen und bestätigen — nicht ins Suchfeld.": "在购物车或结账页面有一个填写优惠券或优惠码的输入框。把优惠码填在那里并确认，不要填进搜索框。",
  "Abzug in der Summe prüfen": "确认总额里已经减掉",
  "Vor dem Abschicken kontrollieren, ob die 10 % in der Summe stehen. Der Betrag im Warenkorb ist der verbindliche — erst dann bestellen.": "提交前先确认总额里已经减去 10%。以购物车里显示的金额为准，确认后再下单。",
