  "Wofür der Code gilt — und wofür nicht.": "这个优惠码管什么，不管什么。",
  "Was hier steht, ist der Stand, den wir kennen. Die Konditionen setzt XXL Nutrition, nicht Camp Dörfl — deshalb steht unten, woran du dich verlässlich halten kannst.": "这里写的是我们所知道的情况。条件由 XXL Nutrition 制定，而不是 Camp Dörfl —— 所以下面写明哪些是你可以放心依据的。",
  "Wo der Rabatt greift": "折扣在哪里生效",
  "Der Code wird auf die laufende Bestellung angerechnet, sobald er im Gutscheinfeld bestätigt ist. Was tatsächlich abgezogen wird, steht in der Summe im Warenkorb — dieser Betrag gilt, nicht die Angabe auf dieser Seite.": "优惠码一经在优惠券输入框确认，就会计入当前订单。实际减免多少，显示在购物车总额里 —— 以那个金额为准，而不是本页面上的说法。",
  "Mögliche Ausnahmen": "可能的例外",
  "Umfang, Mindestbestellwert und Ausnahmen legt XXL Nutrition fest und kann sie jederzeit ändern. Von Camp Dörfl aus gibt es keine Bedingung: kein Mindestwert, keine Anmeldung, keine Laufzeit. Ob der Code für deinen Warenkorb gilt, entscheidet der Warenkorb.": "适用范围、最低订单金额和例外情况由 XXL Nutrition 决定，并可随时更改。Camp Dörfl 这边不设任何条件：没有最低金额、无需注册、没有期限。优惠码对你的购物车是否有效，由购物车说了算。",
