  "auf dieser Website stehen bereits abzüglich der 10 %, rechnen also auf den schon reduzierten Preis. Ob sich der Code mit einer bestimmten Aktion verbinden lässt, entscheidet XXL Nutrition.": "所显示的特惠价已经减去了 10%，也就是在已降价的基础上再算。优惠码能否与某项具体促销叠加，由 XXL Nutrition 决定。",
  "Camp Dörfl ist Nutrition Partner von XXL Nutrition. Aus dieser Zusammenarbeit stammt der Code — er ist kein anonymer Gutschein aus einem Portal, sondern an eine bestehende Partnerschaft geknüpft. Die Zusammenarbeit läuft seit mehreren Jahren; die Produkte werden im eigenen Training und in der Betreuung eingesetzt.": "Camp Dörfl 是 XXL Nutrition 的 Nutrition Partner。这个优惠码正是来自这项合作 —— 它不是某个平台上来路不明的优惠券，而是与一段既有的合作关系绑定的。合作已经持续多年；这些产品也用在自己的训练和学员的日常指导中。",
  "Wie lautet der aktuelle XXL Nutrition Rabattcode?": "当前的 XXL Nutrition 优惠码是什么？",
  "Der aktuelle XXL Nutrition Rabattcode lautet DOMINIK und bringt 10 % Rabatt. Stand: September 2026. Eingetragen wird er bei XXL Nutrition im Warenkorb beziehungsweise an der Kasse im Feld für Gutschein- und Rabattcodes.": "当前的 XXL Nutrition 优惠码是 DOMINIK，可享 10% 折扣。信息截至 2026 年 9 月。在 XXL Nutrition 的购物车或结账页面，把它填进优惠券和优惠码输入框。",
  "Wie viel Rabatt gibt DOMINIK?": "DOMINIK 能打多少折？",
  "DOMINIK zieht 10 % von deiner Bestellung bei XXL Nutrition ab. Der Abzug erscheint im Warenkorb, sobald der Code bestätigt ist. Verbindlich ist der Betrag, der dort steht — nicht die Angabe auf dieser Seite.": "DOMINIK 会为你在 XXL Nutrition 的订单减免 10%。优惠码一经确认，减免就会显示在购物车里。以那里显示的金额为准，而不是本页面上的说法。",
  "Wo gebe ich den XXL Nutrition Code ein?": "XXL Nutrition 的优惠码填在哪里？",
  "Im Warenkorb beziehungsweise im Kassenbereich von xxlnutrition.com gibt es ein Feld für Gutschein- oder Rabattcodes. Dort DOMINIK eintragen und bestätigen. Das Suchfeld ist es nicht — dort passiert nichts.": "在 xxlnutrition.com 的购物车或结账页面，有一个填写优惠券或优惠码的输入框。把 DOMINIK 填在那里并确认。不是搜索框 —— 填在那里不会有任何反应。",
  "Funktioniert der Code auch bei Angeboten?": "特惠商品也能用这个优惠码吗？",
  "Das Wochenangebot-Band auf campdoerfl.de weist die Angebotspreise bereits abzüglich der 10 % aus, rechnet also auf den schon reduzierten Preis. Ob sich der Code mit einer bestimmten Aktion verbinden lässt, legt XXL Nutrition fest und kann es jederzeit ändern. Maßgeblich ist immer die Summe im Warenkorb.": "campdoerfl.de 上的每周特惠栏所显示的特惠价已经减去了 10%，也就是在已降价的基础上再算。优惠码能否与某项具体促销叠加，由 XXL Nutrition 决定，并可随时更改。始终以购物车总额为准。",
  "Gibt es einen XXL Nutrition Influencer Code?": "有 XXL Nutrition 的达人推广码吗？",
  "Ja — DOMINIK ist genau dieser Code. Er stammt aus der Partnerschaft zwischen Camp Dörfl und XXL Nutrition und ist derselbe Code, der sonst als Influencer- oder Creator-Code gesucht wird. Er kostet nichts, ist an keine Bedingung von Camp Dörfl geknüpft und bringt 10 %.": "有 —— DOMINIK 就是这个码。它来自 Camp Dörfl 与 XXL Nutrition 的合作，也就是人们常说的达人码或创作者码。它不收费，Camp Dörfl 这边不附带任何条件，可享 10% 折扣。",
  "Nein. Der Code ist kostenlos, verlangt keine Anmeldung und hat von unserer Seite keinen Mindestbestellwert. Camp Dörfl ist Nutrition Partner von XXL Nutrition; über den Link kann eine Vergütung entstehen, für dich ändert sich am Preis dadurch nichts.": "不收费。这个码免费、无需注册，我们这边也不设最低订单金额。Camp Dörfl 是 XXL Nutrition 的 Nutrition Partner；通过链接可能产生佣金，但你的价格不会因此改变。",
  "Umfang, Mindestbestellwert und mögliche Ausnahmen legt XXL Nutrition selbst fest und kann sie jederzeit ändern. Ob der Code für deinen Warenkorb gilt, zeigt der Warenkorb — dort steht der Abzug oder eben nicht.": "适用范围、最低订单金额和可能的例外由 XXL Nutrition 自行决定，并可随时更改。优惠码对你的购物车是否有效，购物车会告诉你 —— 那里要么显示减免，要么没有。",

